def gen_bk_singal(data){

    // 用于空值填充值
    NULL_BK_CODE = "999999.SI"
    NULL_BK_CODE_NUM = -1

    // data 本身是否有 signal
    is_contain_signal = "signal" in data.columnNames()
    signal_len = 0
    if (is_contain_signal) {
        signal_len = count(data[0]["signal"])
    }

    // 1. 先获取目前的所有的2级板块有哪些
    bk_code_list = exec index_code from loadTable("dfs://tushare_basic_db", "index_classify") where level == "L2"

    // 2. 构建 板块和int的映射表
    nums = 1..count(bk_code_list)-1
    bk_map_dict = dict(bk_code_list, nums)
    bk_map_dict[NULL_BK_CODE] = NULL_BK_CODE_NUM

    bk_map_dict_reverse = dict(nums, bk_code_list)

    if (count(data)==0){
        return data, bk_map_dict_reverse
    }

    // 3. 根据股票 和 时间 添加 行业分类 signal
    // 交易日 从data中推算
    trade_dates = exec distinct date(tradeTime) from data
    // 形成 每日板块标签表
    bk_table = cj(table(trade_dates), table(bk_code_list))
    bk_table.rename!(["tradeDate", "index_code"])
    // left join 添加成分股数据 形成 时间 板块 个股 窄表
    bk_table = select a.*, b.code
        from bk_table a 
        left join (select * from loadTable("dfs://tushare_basic_db", "index_member_all")) b 
        on a.index_code == b.l2_code
        where a.tradeDate >= b.in_date and (isNull(b.out_date) or a.tradeDate < b.out_date) 
        order by tradeDate
    bk_table = select * from bk_table where not isNull(code)
    // left join 合并到行情表上 作为 板块标签
    data_with_bk = select a.*, b.index_code 
                    from data a 
                    left join bk_table b 
                    on date(a.tradeTime) == b.tradeDate and a.symbol == b.code
                order by a.tradeTime, a.symbol
    update data_with_bk set index_code=nullFill(index_code, NULL_BK_CODE)

    index_code_col = data_with_bk.index_code

    // 4. 计算伪板块指数行情
    x = select * from data_with_bk where not isNull(prevClosePrice) and prevClosePrice > 0
    x = select *, open  / prevClosePrice - 1.0 as open_ret, high  / prevClosePrice - 1.0 as high_ret, low   / prevClosePrice - 1.0 as low_ret, close / prevClosePrice - 1.0 as close_ret from x

    sectorAgg = select symbol, tradeTime, 1000.0 * (avg(open_ret)+1) as open, 1000.0 * (avg(low_ret)+1) as low, 1000.0 * (avg(high_ret)+1) as high, 1000.0 * (avg(close_ret)+1) as close, sum(volume).long() as volume, sum(amount) as amount, 999999.0 as upLimitPrice, 0.0 as downLimitPrice, 1000.0 as prevClosePrice from x where index_code != NULL_BK_CODE group by tradeTime, index_code as symbol order by tradeTime, symbol

    // 5. 数据合并 以及 调整到signal中
    drop!(data_with_bk, "index_code")

    // 将 板块 合并到 个股的signal中
    if (is_contain_signal){
        // 原先的 data 中包含 signal
        update data_with_bk set signal=fixedLengthArrayVector(data_with_bk.signal, bk_map_dict[index_code_col])
    } else {
        // 不含  signal
        update data_with_bk set signal=arrayVector(1..count(index_code_col), bk_map_dict[index_code_col])
    }
    signal_len = signal_len+1

    // 给板块行情添加signal列
    sector_num = count(sectorAgg)

    // 没有板块行情的时候，直接返回
    if (sector_num == 0){
        return data_with_bk, bk_map_dict_reverse
    }

    update sectorAgg set signal=arrayVector((1..sector_num)*signal_len, take(-1, sector_num*signal_len))

    // 数据合并
    all_data = select * from unionAll([data_with_bk, sectorAgg], 0) order by tradeTime, symbol

    // 返回值 
        // all_data 包含了板块行情和股票行情，以及股票包含板块标签
        // bk_map_dict_reverse 表示 股票中的signal标签对应的板块 code
    return all_data, bk_map_dict_reverse
}
